const current = $('Fetch Approved Print Jobs').first().json;
const states=$('Read Revision Snapshot').all().map(x=>x.json); const state={values:states.filter(x=>x.Key==='release-register').map(x=>[x.Snapshot])}; if(states.some(x=>x.error)||state.values.length!==1) state.error='Invalid snapshot rows';
let problems=[]; let prior={}; let jobs=[];
if(current.error || !Array.isArray(current.records) || current.offset) problems.push('Current records missing, failed or paginated');
if(state.error || !Array.isArray(state.values) || !state.values[0]?.[0]) problems.push('Snapshot missing. Initialise Snapshot sheet: Key and Snapshot headers; release-register and {} row.');
try { prior=JSON.parse(state.values?.[0]?.[0] || '{}'); if(!prior || Array.isArray(prior) || typeof prior!=='object') throw Error(); } catch {problems.push('Snapshot is not an object');}
for(const r of current.records || []) {
 const f=r.fields||{};
 if(!r.id || !f.JobId || !f.ApprovedRevision || !f.ReleasedRevision || !['queued','plated','printing'].includes(f.PressState) || !Number.isFinite(f.ReprintExposure)) problems.push('Invalid print job '+(r.id||'?'));
 jobs.push({recordId:r.id,jobId:f.JobId,approvedRevision:f.ApprovedRevision,releasedRevision:f.ReleasedRevision,pressState:f.PressState,exposure:f.ReprintExposure,notes:String(f.ChangeNotes||'').slice(0,1500)});
}
jobs.sort((a,b)=>String(a.recordId).localeCompare(String(b.recordId)));
let snapshot={}; let delta=[];
for(const j of jobs){
 const signature=JSON.stringify([j.approvedRevision,j.releasedRevision,j.pressState]);
 snapshot[j.recordId]=signature;
 if(prior[j.recordId]!==signature && j.approvedRevision!==j.releasedRevision) delta.push(j);
}
if(JSON.stringify(snapshot).length>45000) problems.push('Snapshot exceeds safe cell limit');
return [{json:{valid:problems.length===0,problems,jobs,snapshot,delta,changed:delta.length>0}}];

const before=$('Diff Released Revisions').first().json;
const latest=$input.first().json;
if(latest.error || !Array.isArray(latest.records) || latest.offset) throw Error('Debounce recheck failed; snapshot unchanged');
const normalized=latest.records.map(r=>({recordId:r.id,jobId:r.fields?.JobId,approvedRevision:r.fields?.ApprovedRevision,releasedRevision:r.fields?.ReleasedRevision,pressState:r.fields?.PressState,exposure:r.fields?.ReprintExposure,notes:String(r.fields?.ChangeNotes||'').slice(0,1500)})).sort((a,b)=>String(a.recordId).localeCompare(String(b.recordId)));
if(JSON.stringify(normalized)!==JSON.stringify(before.jobs)) return [];
return [{json:{...before,critical:before.delta.some(j=>['plated','printing'].includes(j.pressState)),observedAt:new Date().toISOString()}}];

const d=$('Confirm Stable Revision Delta').first().json, c=$('Normalise Print Configuration').first().json;
let summary='AI explanation unavailable; review the deterministic revision table below.';
try { const p=JSON.parse($input.first().json.text || JSON.stringify($input.first().json)); if(typeof p.summary==='string') summary=p.summary.slice(0,2500); }catch{}
const rows=d.delta.map(j=>`${j.jobId}: approved ${j.approvedRevision}, released ${j.releasedRevision}, press ${j.pressState}, recorded exposure ${j.exposure}`).join('\n');
return [{json:{...d,recipient:c.recipient,slackChannel:c.slackChannel,subject:`[Review required] ${d.delta.length} packaging revision mismatches`,reportText:summary+'\n\n'+rows,slackText:summary.slice(0,1000)+'\n'+rows.slice(0,2200),snapshotText:JSON.stringify(d.snapshot)}}];
